-- Generated by generate.mjs. Speed Reading DB only, after v2 program packs.
-- Publish API and frontend first. Backup required. No deletion or student-history rewrite.
-- Drain/quiesce program starts before applying; table locks do not block template reads.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
SELECT pg_advisory_xact_lock(hashtext('regression-v2'));
LOCK TABLE speed_reading.exercises, speed_reading.exercise_types, speed_reading.reading_texts,
  speed_reading.reading_questions, speed_reading.program_templates IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE regression_settings ON COMMIT DROP AS
SELECT (item->>'id')::uuid id, (item->>'ageGroupId')::uuid age_id, (item->>'level')::int level,
  item->>'previousTitle' old_title, item->'previousConfiguration' old_config,
  item->>'title' title, item->'configuration' config
FROM jsonb_array_elements($settings${{SETTINGS}}$settings$::jsonb) item;
CREATE TEMP TABLE regression_content ON COMMIT DROP AS
SELECT (item->>'id')::uuid id, (item->>'exerciseId')::uuid exercise_id, (item->>'ageGroupId')::uuid age_id,
  (item->>'level')::int level, item->>'title' title, item->>'content' content,
  (item->>'wordCount')::int word_count, item->'questions' questions
FROM jsonb_array_elements($content${{CONTENT}}$content$::jsonb) item;
CREATE TEMP TABLE regression_questions ON COMMIT DROP AS
SELECT (q->>'id')::uuid id, c.id text_id, q->>'questionText' question_text, q->>'correctAnswer' answer,
  q->>'optionA' a, q->>'optionB' b, q->>'optionC' c, q->>'optionD' d, q->>'explanation' explanation,
  q->>'evidence' evidence, (q->>'type')::int type, (q->>'bloomLevel')::int bloom,
  (q->>'orderIndex')::int position, c.level
FROM regression_content c CROSS JOIN LATERAL jsonb_array_elements(c.questions) q;
CREATE TEMP TABLE regression_programs ON COMMIT DROP AS
SELECT (item->>'id')::uuid id, (item->>'ageGroupId')::uuid age_id, (item->>'level')::int level,
  item->'basePattern' base_pattern, item->'previousPattern' old_pattern, item->'pattern' pattern
FROM jsonb_array_elements($programs${{PROGRAMS}}$programs$::jsonb) item;
DO $$ BEGIN
  IF (SELECT count(*) FROM regression_settings)<>19 OR (SELECT count(DISTINCT id) FROM regression_settings)<>19
    OR (SELECT count(*) FROM regression_settings WHERE old_config<>'null'::jsonb)<>6
    OR (SELECT count(*) FROM regression_content)<>57 OR (SELECT count(DISTINCT id) FROM regression_content)<>57
    OR (SELECT count(*) FROM regression_questions)<>285 OR (SELECT count(DISTINCT id) FROM regression_questions)<>285
    OR (SELECT count(*) FROM regression_programs)<>19 OR (SELECT count(DISTINCT id) FROM regression_programs)<>19
    THEN RAISE EXCEPTION 'Regression payload incomplete'; END IF;
  IF (SELECT count(*) FROM speed_reading.exercise_types WHERE name='RegressionReduction'
    AND engine_type='regression_reduction' AND is_active AND NOT is_deleted)<>1
    THEN RAISE EXCEPTION 'Active Regression type missing or ambiguous'; END IF;
  IF EXISTS(SELECT 1 FROM regression_settings s LEFT JOIN speed_reading.exercises e ON e.id=s.id
    LEFT JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
    WHERE (s.old_config<>'null'::jsonb AND e.id IS NULL) OR (e.id IS NOT NULL AND
      (t.name IS DISTINCT FROM 'RegressionReduction' OR e.target_age_group_id IS DISTINCT FROM s.age_id
       OR e.difficulty_level<>s.level OR NOT e.is_active OR e.is_deleted
       OR (e.configuration_json IS DISTINCT FROM s.config AND e.configuration_json IS DISTINCT FROM s.old_config)
       OR (e.title IS DISTINCT FROM s.title AND e.title IS DISTINCT FROM s.old_title))))
    THEN RAISE EXCEPTION 'Regression catalog baseline changed'; END IF;
  IF EXISTS(SELECT 1 FROM speed_reading.exercises e JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
    WHERE t.name='RegressionReduction' AND e.is_active AND NOT e.is_deleted
      AND e.target_age_group_id IN (SELECT age_id FROM regression_settings)
      AND NOT EXISTS(SELECT 1 FROM regression_settings s WHERE s.id=e.id))
    THEN RAISE EXCEPTION 'Unexpected age-specific Regression entry'; END IF;
  IF EXISTS(SELECT 1 FROM regression_content c LEFT JOIN regression_settings s ON s.id=c.exercise_id
    WHERE s.id IS NULL OR c.age_id IS DISTINCT FROM s.age_id OR c.level<>s.level
      OR cardinality(regexp_split_to_array(btrim(c.content), E'\\s+'))<>c.word_count
      OR c.word_count<(s.config->'engineConfig'->'content'->>'minWordCount')::int
      OR c.word_count>(s.config->'engineConfig'->'content'->>'maxWordCount')::int
      OR jsonb_array_length(c.questions)<>5)
    THEN RAISE EXCEPTION 'Regression content band/question mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM regression_settings s LEFT JOIN regression_content c ON c.exercise_id=s.id
    GROUP BY s.id HAVING count(c.id)<>3 OR count(DISTINCT c.content)<>3)
    THEN RAISE EXCEPTION 'Regression needs three distinct texts per age/level'; END IF;
  IF EXISTS(SELECT 1 FROM regression_questions q JOIN regression_content c ON c.id=q.text_id
    WHERE q.type NOT BETWEEN 1 AND 3 OR q.bloom NOT BETWEEN 1 AND 6 OR q.answer NOT IN ('A','B','C','D')
      OR btrim(q.a)='' OR btrim(q.b)='' OR btrim(q.c)='' OR btrim(q.d)=''
      OR btrim(q.evidence)='' OR strpos(c.content,q.evidence)=0)
    THEN RAISE EXCEPTION 'Regression question quality/evidence mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM regression_content c JOIN speed_reading.reading_texts t ON t.id=c.id
    WHERE t.title IS DISTINCT FROM c.title OR t.content IS DISTINCT FROM c.content OR t.word_count<>c.word_count
      OR t.exercise_id IS DISTINCT FROM c.exercise_id OR t.target_age_group_id IS DISTINCT FROM c.age_id
      OR t.difficulty_level<>c.level OR NOT t.is_active OR t.is_deleted)
    THEN RAISE EXCEPTION 'Regression text collision or later edit'; END IF;
  IF EXISTS(SELECT 1 FROM regression_questions q JOIN speed_reading.reading_questions r ON r.id=q.id
    WHERE r.reading_text_id<>q.text_id OR r.question_text IS DISTINCT FROM q.question_text
      OR r.correct_answer IS DISTINCT FROM q.answer OR r.option_a IS DISTINCT FROM q.a
      OR r.option_b IS DISTINCT FROM q.b OR r.option_c IS DISTINCT FROM q.c OR r.option_d IS DISTINCT FROM q.d
      OR r.explanation IS DISTINCT FROM q.explanation OR r.type<>q.type OR r.bloom_level<>q.bloom
      OR r.difficulty_level<>q.level OR r.order_index<>q.position OR r.is_deleted)
    THEN RAISE EXCEPTION 'Regression question collision or later edit'; END IF;
  IF EXISTS(SELECT 1 FROM regression_programs g LEFT JOIN speed_reading.program_templates p ON p.id=g.id
    WHERE p.id IS NULL OR NOT p."IsActive" OR p."IsDeleted" OR p."IsAssessment"
      OR p."InitialDifficultyLevel"<>g.level OR p."TotalDays"<>28 OR p."TotalWeeks"<>4
      OR p."TargetAgeGroupConfigurationId" IS DISTINCT FROM g.age_id
      OR (p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.base_pattern
        AND p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.old_pattern AND p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.pattern))
    THEN RAISE EXCEPTION 'Regression program baseline changed'; END IF;
END $$;
INSERT INTO speed_reading.exercises(id,exercise_type_id,title,description,type_code,difficulty_level,
  configuration_json,target_age_group_id,creator_id,is_active,created_at,created_by,version,is_deleted)
SELECT s.id,t.id,s.title,'Maskelenen geçmiş kelimelerle sabit tempolu metin takibi; sonunda beş anlama sorusu.',
  'reading',s.level,s.config,s.age_id,seed.creator_id,true,now(),'regression-v2',1,false
FROM regression_settings s CROSS JOIN speed_reading.exercise_types t
CROSS JOIN LATERAL (SELECT e.creator_id FROM speed_reading.exercises e
  WHERE e.exercise_type_id=t.id AND e.is_active AND NOT e.is_deleted ORDER BY e.id LIMIT 1) seed
WHERE t.name='RegressionReduction' AND s.old_config='null'::jsonb ON CONFLICT(id) DO NOTHING;
INSERT INTO speed_reading.reading_texts(id,title,content,word_count,category,difficulty_level,target_age_group_id,
  language,is_active,tags,recommended_min_level,recommended_max_level,average_comprehension_score,times_read,
  average_reading_time_seconds,exercise_id,created_at,created_by,version,is_deleted)
SELECT id,title,content,word_count,'regression',level,age_id,'tr',true,'regression-v2;original-selection',level,level,
  0,0,0,exercise_id,now(),'regression-v2',1,false FROM regression_content ON CONFLICT(id) DO NOTHING;
INSERT INTO speed_reading.reading_questions(id,reading_text_id,question_text,type,bloom_level,difficulty_level,
  explanation,option_a,option_b,option_c,option_d,correct_answer,order_index,created_at,created_by,is_deleted)
SELECT id,text_id,question_text,type,bloom,level,explanation,a,b,c,d,answer,position,now(),'regression-v2',false
FROM regression_questions ON CONFLICT(id) DO NOTHING;
UPDATE speed_reading.exercises e SET configuration_json=s.config,title=s.title,updated_at=now(),
  updated_by='regression-v2',version=e.version+1 FROM regression_settings s
WHERE e.id=s.id AND (e.configuration_json IS DISTINCT FROM s.config OR e.title IS DISTINCT FROM s.title);
DO $$ BEGIN
  IF (SELECT count(*) FROM regression_settings s JOIN speed_reading.exercises e ON e.id=s.id
    WHERE e.configuration_json=s.config AND e.title=s.title AND e.is_active AND NOT e.is_deleted)<>19
    THEN RAISE EXCEPTION 'Regression final catalog verification failed'; END IF;
  IF EXISTS(SELECT 1 FROM regression_programs p
    CROSS JOIN LATERAL jsonb_each(p.pattern) week
    CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(week.value)='object' THEN week.value ELSE '{}'::jsonb END) day
    CROSS JOIN LATERAL jsonb_array_elements(day.value) task
    WHERE NOT EXISTS(SELECT 1 FROM speed_reading.exercises e JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
      WHERE t.name=task->>'type' AND e.difficulty_level=(task->>'difficulty')::int AND e.target_age_group_id=p.age_id
        AND e.is_active AND NOT e.is_deleted AND t.is_active AND NOT t.is_deleted))
    THEN RAISE EXCEPTION 'Regression program has an unavailable exercise'; END IF;
END $$;
UPDATE speed_reading.program_templates p SET "WeeklyPatternJson"=g.pattern,
  updated_at=now(),updated_by='regression-v2',version=p.version+1 FROM regression_programs g
WHERE p.id=g.id AND p."WeeklyPatternJson"::jsonb IS DISTINCT FROM g.pattern;
COMMIT;
